    // Utility: deterministic color from string
    function colorFromId(id) {
            let h = 0;
            for (let i = 0; i < id.length; i++) h = (h << 5) - h + id.charCodeAt(i);
            const r = (h >> 16) & 0xff, g = (h >> 8) & 0xff, b = h & 0xff;
            return `rgb(${(r+256)%256}, ${(g+256)%256}, ${(b+256)%256})`;
    }

    // Ensure every skin has visual definitions (attackEffect, superEffect)
    function ensureSkinVisuals() {
            for (const k in skinsDatabase) {
                    const s = skinsDatabase[k];
                    const baseColor = (s.attackEffect && s.attackEffect.color) || (s.superEffect && s.superEffect.color) || colorFromId(s.id || k);
                    if (!s.attackEffect) s.attackEffect = { type: 'defaultAttack', color: baseColor, glow: false };
                    if (!s.superEffect) s.superEffect = { type: 'defaultSuper', color: baseColor, glow: true };
                    s._displayColor = s._displayColor || baseColor;
            }
    }
    ensureSkinVisuals();

    const SKIN_RARITY_META = {
        'super-rare': { label: 'Super Rare', border: '#5df2c2', glow: '#5df2c2', effects: 'Custom attack effects only' },
        'epic': { label: 'Epic', border: '#9b59b6', glow: '#9b59b6', effects: 'Custom attack and super effects' },
        'mythic': { label: 'Mythic', border: '#ff6b6b', glow: '#ff6b6b', effects: 'Current visuals plus takedown effect' },
        'legendary': { label: 'Legendary', border: '#ffd700', glow: '#ffd700', effects: 'Everything: spawn, attack, super, takedown, death' }
    };

    function getActiveSkinForBrawler(brawlerId) {
        if (!brawlerId) return null;
        if (typeof playerData === 'undefined' || !playerData) return null;
        const skinId = (playerData.selectedSkins && playerData.selectedSkins[brawlerId]) ||
                       (playerData.activeSkins && playerData.activeSkins[brawlerId]) ||
                       (playerData.equippedSkins && playerData.equippedSkins[brawlerId]);
        if (!skinId || skinId === 'default' || skinId === 'none') return null;
        if (typeof skinsDatabase !== 'undefined' && skinsDatabase[skinId]) {
            return skinsDatabase[skinId];
        }
        if (typeof brawlerSkins !== 'undefined' && Array.isArray(brawlerSkins[brawlerId])) {
            const found = brawlerSkins[brawlerId].find(s => s && s.id === skinId);
            if (found) return found;
        }
        return null;
    }


    function renderUniversalSkinProjectile(b, skin) {
        if (!b || !skin) return false;
        const effect = b.super ? skin.superEffect : skin.attackEffect;
        if (!effect) return false;

        const projectileBrawler = b.ownerBrawler || (b.ownerId === (typeof player !== 'undefined' ? player.id : '') ? (typeof selectedBrawler !== 'undefined' ? selectedBrawler : '') : '');
        if (skin.brawler && projectileBrawler && projectileBrawler !== skin.brawler) return false;

        // Don't override special visual flags that have dedicated render blocks
        if (b.isMagenyMagnet || b.isTrappedInMagenyVortex || b.isOrboSuper || b.isOrboMain || b.isHomerProjectile || b.isRocketeerMain || b.isRocketeerMini || b.isClassyNote || b.isFuserBullet) return false;

        const color = effect.color || skin._displayColor || '#00d2d3';
        const radius = Math.max(4, (b.hitboxMod || 1) * (b.radius || 6));
        const angle = Math.atan2(b.vy || 0, b.vx || 1);

        ctx.save();
        ctx.translate(b.x, b.y);
        ctx.rotate(angle);

        if (effect.glow || skin.rarity === 'mythic' || skin.rarity === 'legendary') {
            ctx.shadowColor = color;
            ctx.shadowBlur = 14;
        }

        const speed = Math.hypot(b.vx || 0, b.vy || 0) || 1;
        const tailLen = Math.min(28, speed * 0.04);

        // Trail
        ctx.strokeStyle = color;
        ctx.lineWidth = radius * 1.2;
        ctx.lineCap = 'round';
        ctx.globalAlpha = 0.5;
        ctx.beginPath();
        ctx.moveTo(-tailLen, 0);
        ctx.lineTo(0, 0);
        ctx.stroke();

        // Core
        ctx.globalAlpha = 1.0;
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.arc(0, 0, radius, 0, Math.PI * 2);
        ctx.fill();

        // Bright Center
        ctx.fillStyle = '#ffffff';
        ctx.beginPath();
        ctx.arc(0, 0, radius * 0.45, 0, Math.PI * 2);
        ctx.fill();

        ctx.restore();
        return true;
    }

    function getSkinRarityMeta(rarity) {
        return SKIN_RARITY_META[rarity] || SKIN_RARITY_META['super-rare'];
    }

    function getFeaturedDurationMs(skin) {
        return (skin?.featuredDurationDays || 5) * 24 * 60 * 60 * 1000;
    }

    function getFeaturedGemPrice(skin) {
        if (typeof skin?.featuredPrice === 'number') return skin.featuredPrice;
        const discount = skin?.featuredDiscount || 0;
        return Math.max(1, Math.round((skin?.price || 0) * (1 - discount)));
    }

    function triggerSkinPulse(entity, skin, kind) {
        if (!entity || !skin) return;
        const effect = skin[kind + 'Effect'];
        if (!effect) return;
        const color = effect.color || getSkinRarityMeta(skin.rarity).border;
        const radius = kind === 'spawn' ? 42 : (kind === 'death' ? 56 : 46);
        const life = kind === 'spawn' ? 0.25 : 0.3;
        const isLegendaryPulse = skin.rarity === 'legendary';

        explosions.push({
            x: entity.x,
            y: entity.y,
            radius,
            life: 0,
            maxLife: life,
            color,
            fxKind: kind,
            legendary: isLegendaryPulse || skin.rarity === 'mythic',
            skinId: skin.id,
            ringCount: kind === 'death' ? 4 : (kind === 'takedown' ? 3 : 2)
        });

        if (isLegendaryPulse) {
            const sparkCount = kind === 'death' ? 18 : (kind === 'takedown' ? 14 : 12);
            const sparkSpeed = kind === 'death' ? 240 : (kind === 'takedown' ? 210 : 180);
            for (let i = 0; i < sparkCount; i++) {
                const ang = (Math.PI * 2 * i) / sparkCount + (Math.random() * 0.18 - 0.09);
                explosions.push({
                    x: entity.x,
                    y: entity.y,
                    vx: Math.cos(ang) * (sparkSpeed + Math.random() * 70),
                    vy: Math.sin(ang) * (sparkSpeed + Math.random() * 70),
                    radius: kind === 'death' ? 2.5 : 2,
                    life: 0,
                    maxLife: kind === 'death' ? 0.9 : 0.7,
                    color: skin.id === 'icy-zapper-miser'
                        ? (kind === 'spawn' ? '#e0ffff' : (kind === 'death' ? '#add8e6' : '#00bfff'))
                        : (kind === 'spawn' ? '#ffb84d' : (kind === 'death' ? '#ff5a1f' : '#ff8c2d')),
                    isParticle: true,
                    legendary: true
                });
            }
        }
    }

