      if(def.id==='fairy'){const left=Math.max(0,(owner.packetEffectCooldownUntil||0)-now);return {label:left?`${Math.ceil(left/1000)}s`:'READY',meter:left?1-left/def.cooldownMs:1,active:!left};}
