            isDead: false,
            shield: 0,
            shieldMax: 0,
            shieldDecayTimer: 0,
            reloadBuffUntil: 0,
            radius: 56,
            speed: 0,
            slowUntil: 0,
            brawler: 'outlit',
            level: 11,
            gadgetUnlocked: false,
            starPowerUnlocked: false,
            hyperchargeUnlocked: false,
            lastTargetId: null,
            targetLockUntil: 0,
            lastShot: 0,
            superCharge: 0,
            hyperChargeCharge: 0,
            isHypercharged: false,
            hyperchargeUntil: 0,
            gadgetArmed: false,
            gadgetCooldownUntil: 0,
            selectedStar: 'none',
            selectedGadget: 'g1',
