        const rawRange = Math.min(SKELEFLYING_SUPER_MAX_RANGE, Math.hypot(targetX - bot.x, targetY - bot.y));
        const superRange = Math.max(SKELEFLYING_SUPER_MIN_DROP_DIST, rawRange);
