      const sin = Math.sin(ang);
      const perpCos = -sin;
      const perpSin = cos;
      const halfW = 90;
      const dist = 520;
      const sx = player.x;
      const sy = player.y;
      const ex = sx + cos * dist;
      const ey = sy + sin * dist;

      // Rail 1 (Left Edge)
      drainbowPrismBarriers.push({
          x1: sx + perpCos * halfW, y1: sy + perpSin * halfW,
          x2: ex + perpCos * halfW, y2: ey + perpSin * halfW,
          until: now + 3500, ownerId: player.id
      });
      // Rail 2 (Right Edge)
