        let draftPhase = 0;
        let playerBan1 = null;
        let playerBan2 = null;
        let aiBan1 = null;
        let aiBan2 = null;
        let playerPick = null;
        let teammatePicks = [null, null];
        let enemyPicks = [null, null, null];
        let activeSelection = null;
        let draftSearchQuery = '';
        let aiTurnTimer = null;

