  function rollTowerDuelPowerLoadouts(team) {
      const result = {};
      for (const id of team) {
          const deck = [...getActiveSlopSushiDeck(id)].sort(() => Math.random() - .5);
          result[id] = deck.slice(0, 2).map(card => card.id);
      }
      return result;
  }

