                header.textContent = kind === 'gadget' ? 'TOOL' : kind === 'star' ? 'TALENT' : kind === 'hc' ? 'CORE SURGE' : kind === 'super' ? 'POWER MOVE' : 'ATTACK';

                const desc = document.createElement('div');
