                b.style.cursor = 'pointer'; b.style.boxShadow = '0 10px 20px rgba(0,0,0,0.24)';
                if ((icon.key === 'gadget' && pData.gadgetUnlocked) || (icon.key === 'star' && pData.starPowerUnlocked) || (icon.key === 'hc' && pData.hyperchargeUnlocked)) {
                    b.style.background = typeof icon.color === 'number' ? '#' + icon.color.toString(16).padStart(6,'0') : icon.color;
                }
                b.onclick = () => openAbilityModal(icon.key);
                iconRow.appendChild(b);
