          return {
              label: isSuper ? `POISON ACTIVE  •  ${prog.label}` : `UPGRADE PROGRESS  •  ${prog.label}`,
              value: prog.stage >= 5 ? 4 : (prog.stage - 1) + prog.pct,
              max: 4,
              color
          };
