        function drawBrawlerPortrait(entity, drawY, isPlayer, fallbackColor, isBoss) {
            if (!entity) return;
            const brawlerId = getEntityRenderBrawler(entity, isPlayer);
            if (drawFeatured2p5DBrawler(entity, drawY, brawlerId, isBoss)) return;
            const data = brawlerData[brawlerId] || {};
            const ex = Number.isFinite(entity.x) ? entity.x : (typeof player !== 'undefined' && Number.isFinite(player.x) ? player.x : 500);
            const ey = Number.isFinite(entity.y) ? entity.y : (typeof player !== 'undefined' && Number.isFinite(player.y) ? player.y : 500);
            const rad = Number.isFinite(entity.radius) ? entity.radius : 14;
            const size = Math.max(22, rad * 2.1);
            const x = ex - size * 0.5;
            const y = (Number.isFinite(drawY) ? drawY : ey) - size * 0.5;
            const activeSkin = getActiveSkinForBrawler(brawlerId);
            const icon = activeSkin?.icon || getBrawlerPortraitIcon(brawlerId);
            const baseColor = (entity.pickleJarHyper||entity.pickleHyper)?'#b54ee8':(activeSkin?._displayColor || data.color || fallbackColor || '#8aa3c4');
            const grad = ctx.createLinearGradient(x, y, x + size, y + size);
            grad.addColorStop(0, baseColor);
            grad.addColorStop(1, '#1a2742');

            drawRoundedRectPath(x, y, size, size, Math.max(6, size * 0.22));
            ctx.fillStyle = grad;
            ctx.fill();

            ctx.lineWidth = isBoss ? 3 : 2;
            ctx.strokeStyle = isBoss ? '#ffd6d6' : 'rgba(230, 245, 255, 0.85)';
            ctx.stroke();

            ctx.fillStyle = 'rgba(0,0,0,0.16)';
            drawRoundedRectPath(x + 2, y + size * 0.54, size - 4, size * 0.42, Math.max(4, size * 0.12));
            ctx.fill();

            ctx.font = `900 ${Math.max(12, Math.round(size * 0.58))}px sans-serif`;
            ctx.textAlign = 'center';
            ctx.textBaseline = 'middle';
            ctx.fillStyle = '#ffffff';
            ctx.fillText(icon, entity.x, drawY + 1);
            if (activeSkin) {
                const pulse = 0.82 + Math.sin(performance.now() / 180) * 0.18;
                ctx.strokeStyle = activeSkin._displayColor || '#ffffff';
                ctx.globalAlpha = 0.55 * pulse;
                ctx.lineWidth = activeSkin.rarity === 'legendary' ? 3.5 : 2;
                ctx.beginPath(); ctx.arc(entity.x, drawY, size * 0.59, 0, Math.PI * 2); ctx.stroke();
                ctx.globalAlpha = 1;
            }
            if (brawlerId === 'jetpack') {
                const airborne=!!entity.jetpackFlight;
                const flicker=.78+Math.sin(performance.now()/42)*.22;
                ctx.save();
                ctx.shadowColor=entity.jetpackFlight?.hyper?'#d96cff':'#53ddff';ctx.shadowBlur=airborne?18:8;
                ctx.fillStyle='#41536e';
                drawRoundedRectPath(x-7,y+size*.25,9,size*.58,4);ctx.fill();
                drawRoundedRectPath(x+size-2,y+size*.25,9,size*.58,4);ctx.fill();
                ctx.fillStyle='#9cecff';ctx.beginPath();ctx.arc(x-2,y+size*.42,3,0,Math.PI*2);ctx.arc(x+size+2,y+size*.42,3,0,Math.PI*2);ctx.fill();
                if(airborne){
                    const flame=12+18*flicker;
                    const grad=ctx.createLinearGradient(0,y+size*.75,0,y+size+flame);grad.addColorStop(0,'#fff7a3');grad.addColorStop(.35,'#ff9c38');grad.addColorStop(1,entity.jetpackFlight?.hyper?'rgba(205,70,255,0)':'rgba(51,202,255,0)');
                    ctx.fillStyle=grad;
                    for(const fx of [x-2,x+size+2]){ctx.beginPath();ctx.moveTo(fx-4,y+size*.68);ctx.quadraticCurveTo(fx-7,y+size+flame*.45,fx,y+size+flame);ctx.quadraticCurveTo(fx+7,y+size+flame*.45,fx+4,y+size*.68);ctx.fill();}
                }
                ctx.restore();
            }
            ctx.textAlign = 'left';
            ctx.textBaseline = 'alphabetic';
    }

