        if (!owner || ownerBrawler !== 'heater_miser') continue;
        const tgtEntity = owner.heaterTetherTargetId ? (owner.heaterTetherTargetId === player.id ? player : bots.find(b => b.id === owner.heaterTetherTargetId)) : null;
        const tgtBox = owner.heaterTetherTargetWall;
        if (!tgtEntity && !tgtBox) continue;
        const tx = tgtEntity ? tgtEntity.x : (tgtBox.x + tgtBox.w / 2);
        const ty = tgtEntity ? tgtEntity.y : (tgtBox.y + tgtBox.h / 2);
        const tz = tgtEntity ? (tgtEntity.z || 0) : 0;
        const warning = !!(owner.heaterTetherBreakWarnUntil && owner.heaterTetherBreakWarnUntil > performance.now());
        const pulse = 0.5 + Math.sin(performance.now() / 120) * 0.22;
